Item.method_code:
const {
	getState,
	commandFactory,
	polySources,
	relatedItemType
} = options;

const { grid } = getState();
const { selectedRows } = grid;
const { rows } = window.grid._grid;

const areRelatedItems = selectedRows.every((rowId) => {
	const relatedId = rows.get(rowId, 'related_id');
	return !!relatedId;
});

if (!areRelatedItems) {
	return Promise.resolve(null);
}
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(relatedItemType?.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return relatedItemType;
};

const createCommandFromRow = (commandAlias, rowId) => {
	const relatedId = rows.get(rowId, 'related_id');
	const item = rows.get(relatedId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	return commandFactory(commandAlias, { item, itemType, itemTypeName });
};

const canExecuteCommand = (commandAlias) => {
	const canExecute = selectedRows.every((rowId) => {
		const command = createCommandFromRow(commandAlias, rowId);
		return command.canExecute();
	});

	return canExecute;
};

const executeCommand = (commandAlias) => {
	const promises = selectedRows.map((rowId) => {
		const command = createCommandFromRow(commandAlias, rowId);
		return command.execute();
	});

	return Promise.allSettled(promises);
};

let commandAlias = target['command_alias@keyed_name'];
const canExecuteClaim = canExecuteCommand(commandAlias);
if (canExecuteClaim) {
	return executeCommand(commandAlias);
}

commandAlias = 'UnclaimItem';
const canExecuteUnclaim = canExecuteCommand(commandAlias);
if (canExecuteUnclaim) {
	return executeCommand(commandAlias);
}

return Promise.resolve(null);
